import Header from '../components/Header';
import Footer from '../components/Footer';
import React from 'react';
import '../styles/Partitions.css';
import * as a from '../assets';

function Partitions() {
    return (
        <div>
            <Header />
            <main className="partitions-main">
                <h1>Partitions</h1>

                {/* Version iframe */}
                <div className="pdf-container">
                    <iframe
                        src="/documents/game_of_throne.pdf"
                        width="100%"
                        height="600px"
                        title="Partition Game of Thrones"
                        style={{ border: '2px solid #00ffff', borderRadius: '8px' }}
                    />
                </div>

                {/* Version bouton pour ouvrir le PDF dans un nouvel onglet */}
                <div style={{ marginTop: '20px' }}>
                    <a
                        href="/documents/game_of_throne.pdf"
                        target="_blank"
                        rel="noreferrer"
                        className="pdf-button"
                    >
                        Ouvrir le PDF en plein écran
                    </a>
                </div>
            </main>
            <Footer />
        </div>
    )
}



export default Partitions;
